"""Header-based claim extraction for trusted proxy mode and local mock mode."""

from __future__ import annotations

import json

from fastapi import Request

from backend.app.shared.auth.errors import InvalidIdentityError, MissingIdentityError
from backend.app.shared.auth.models import RawIdentityClaims
from backend.app.shared.config.auth_config import AuthSettings


class HeaderClaimsExtractor:
    """Extracts raw identity claims from trusted headers."""

    def __init__(self, settings: AuthSettings) -> None:
        self._settings = settings

    def has_identity_material(self, request: Request) -> bool:
        if self._settings.auth_mode == "mock":
            headers = request.headers
            return any(
                header_name in headers
                for header_name in (
                    self._settings.mock_subject_header,
                    self._settings.mock_email_header,
                    self._settings.mock_display_name_header,
                    self._settings.mock_groups_header,
                )
            )
        return self._settings.claims_header_name in request.headers

    def extract(self, request: Request) -> RawIdentityClaims:
        if self._settings.auth_mode == "mock":
            return self._extract_mock_claims(request)
        if self._settings.auth_mode == "proxy":
            return self._extract_proxy_claims(request)
        raise InvalidIdentityError(f"Unsupported auth mode: {self._settings.auth_mode}")

    def _extract_mock_claims(self, request: Request) -> RawIdentityClaims:
        headers = request.headers
        subject = headers.get(self._settings.mock_subject_header)
        if subject is None or subject.strip() == "":
            raise MissingIdentityError("Authentication required.")

        email = headers.get(self._settings.mock_email_header, "")
        display_name = headers.get(self._settings.mock_display_name_header, "")
        groups = headers.get(self._settings.mock_groups_header, "")

        mapping = self._settings.claim_mapping
        return RawIdentityClaims(
            provider="mock",
            claims={
                mapping.subject_claim: subject,
                mapping.email_claim: email,
                mapping.display_name_claim: display_name,
                mapping.groups_claim: groups,
            },
        )

    def _extract_proxy_claims(self, request: Request) -> RawIdentityClaims:
        raw_claims = request.headers.get(self._settings.claims_header_name)
        if raw_claims is None or raw_claims.strip() == "":
            raise MissingIdentityError("Authentication required.")

        try:
            parsed = json.loads(raw_claims)
        except json.JSONDecodeError as exc:
            raise InvalidIdentityError("Invalid claims header.") from exc

        if not isinstance(parsed, dict):
            raise InvalidIdentityError("Claims header must decode to a JSON object.")

        return RawIdentityClaims(provider=self._settings.provider, claims=parsed)
