"""Group to role and permission resolution."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Mapping

PERMISSION_ORDER: tuple[str, ...] = ("upload", "validate", "search", "export", "qa")


@dataclass(frozen=True)
class RolePermissionResolver:
    group_role_map: Mapping[str, tuple[str, ...]]
    role_permissions: Mapping[str, tuple[str, ...]]
    role_priority: tuple[str, ...]

    def resolve_roles(self, groups: tuple[str, ...]) -> tuple[str, ...]:
        resolved: list[str] = []
        for group in groups:
            for role in self.group_role_map.get(group, ()):
                if role not in resolved:
                    resolved.append(role)

        if not resolved:
            return ("viewer",)

        return tuple(sorted(resolved, key=self._role_sort_key))

    def resolve_permissions(self, groups: tuple[str, ...]) -> tuple[str, ...]:
        return self.resolve_permissions_for_roles(self.resolve_roles(groups))

    def resolve_permissions_for_roles(self, roles: tuple[str, ...]) -> tuple[str, ...]:
        collected: list[str] = []
        for role in roles:
            for permission in self.role_permissions.get(role, ()):
                if permission not in collected:
                    collected.append(permission)

        return tuple(sorted(collected, key=self._permission_sort_key))

    def primary_role(self, roles: tuple[str, ...]) -> str:
        if len(roles) == 0:
            return "viewer"
        return roles[0]

    def _role_sort_key(self, role: str) -> int:
        try:
            return self.role_priority.index(role)
        except ValueError:
            return len(self.role_priority)

    def _permission_sort_key(self, permission: str) -> int:
        try:
            return PERMISSION_ORDER.index(permission)
        except ValueError:
            return len(PERMISSION_ORDER)
