"""User persistence port and SQLAlchemy implementation."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Any, Callable, Protocol
from uuid import uuid4

from sqlalchemy import Boolean, DateTime, MetaData, String, Table, Uuid, Column, insert, select, update
from sqlalchemy.engine import Engine
from sqlalchemy.orm import Session, sessionmaker

from backend.app.shared.auth.models import AuthenticatedIdentity, PersistedUser

identity_metadata = MetaData()

users_table = Table(
    "users",
    identity_metadata,
    Column("id", Uuid, primary_key=True, nullable=False),
    Column("external_subject", String, nullable=False, unique=True),
    Column("email", String, nullable=False, unique=True),
    Column("display_name", String, nullable=False),
    Column("role", String, nullable=False),
    Column("is_active", Boolean, nullable=False, default=True),
    Column("last_login_at", DateTime(timezone=True), nullable=True),
)


class UserIdentityRepository(Protocol):
    def upsert_authenticated_user(
        self, identity: AuthenticatedIdentity, occurred_at: datetime
    ) -> PersistedUser:
        """Insert or update the authenticated user record."""


@dataclass(frozen=True)
class SQLAlchemyUserIdentityRepository:
    session_factory: Callable[[], Session]

    def upsert_authenticated_user(
        self, identity: AuthenticatedIdentity, occurred_at: datetime
    ) -> PersistedUser:
        with self.session_factory() as session:
            with session.begin():
                existing = (
                    session.execute(
                        select(users_table).where(
                            users_table.c.external_subject == identity.subject
                        )
                    )
                    .mappings()
                    .first()
                )

                if existing is None:
                    user_id = uuid4()
                    session.execute(
                        insert(users_table).values(
                            id=user_id,
                            external_subject=identity.subject,
                            email=identity.email,
                            display_name=identity.display_name,
                            role=identity.primary_role,
                            is_active=True,
                            last_login_at=occurred_at,
                        )
                    )
                else:
                    user_id = existing["id"]
                    session.execute(
                        update(users_table)
                        .where(users_table.c.id == user_id)
                        .values(
                            email=identity.email,
                            display_name=identity.display_name,
                            role=identity.primary_role,
                            is_active=True,
                            last_login_at=occurred_at,
                        )
                    )

                persisted = (
                    session.execute(select(users_table).where(users_table.c.id == user_id))
                    .mappings()
                    .one()
                )

        return _row_to_persisted_user(persisted)


def build_session_factory(engine: Engine) -> Callable[[], Session]:
    maker = sessionmaker(bind=engine, future=True)
    return maker


def _row_to_persisted_user(row: Any) -> PersistedUser:
    return PersistedUser(
        id=str(row["id"]),
        external_subject=str(row["external_subject"]),
        email=str(row["email"]),
        display_name=str(row["display_name"]),
        role=str(row["role"]),
        is_active=bool(row["is_active"]),
        last_login_at=row["last_login_at"],
    )
