"""FastAPI app factory for REQ-002 auth and RBAC behavior."""

from __future__ import annotations

from datetime import datetime
import os
from typing import Callable

from fastapi import Depends, FastAPI, Request
from fastapi.responses import JSONResponse
from sqlalchemy import create_engine

from backend.app.identity.auth.dependencies import (
    require_authenticated_session,
    require_permission,
)
from backend.app.identity.auth.repository import (
    SQLAlchemyUserIdentityRepository,
    build_session_factory,
)
from backend.app.identity.auth.service import IdentityAccessService, utc_now
from backend.app.shared.auth.errors import AuthenticationError, AuthorizationError
from backend.app.shared.auth.extractors import HeaderClaimsExtractor
from backend.app.shared.auth.models import AuthenticatedSession
from backend.app.shared.auth.normalizer import IdentityNormalizer
from backend.app.shared.config.auth_config import AuthSettings
from backend.app.shared.rbac.service import RolePermissionResolver


def create_app(
    settings: AuthSettings | None = None,
    user_repository: SQLAlchemyUserIdentityRepository | None = None,
    clock: Callable[[], datetime] = utc_now,
) -> FastAPI:
    resolved_settings = settings or AuthSettings.from_env()
    repository = user_repository or _build_repository_from_env()
    role_resolver = RolePermissionResolver(
        group_role_map=resolved_settings.group_role_map,
        role_permissions=resolved_settings.role_permissions,
        role_priority=resolved_settings.role_priority,
    )
    service = IdentityAccessService(
        claims_extractor=HeaderClaimsExtractor(resolved_settings),
        identity_normalizer=IdentityNormalizer(
            claim_mapping=resolved_settings.claim_mapping,
            role_permission_resolver=role_resolver,
            group_delimiter=resolved_settings.group_delimiter,
        ),
        user_repository=repository,
        clock=clock,
    )

    app = FastAPI(title="REQ-002 Identity Access Service")
    app.state.identity_access_service = service

    @app.exception_handler(AuthenticationError)
    async def handle_authentication_error(
        request: Request, exc: AuthenticationError
    ) -> JSONResponse:
        return JSONResponse(
            status_code=401,
            content={"detail": {"code": "unauthorized", "message": str(exc)}},
        )

    @app.exception_handler(AuthorizationError)
    async def handle_authorization_error(
        request: Request, exc: AuthorizationError
    ) -> JSONResponse:
        return JSONResponse(
            status_code=403,
            content={"detail": {"code": "forbidden", "message": str(exc)}},
        )

    @app.middleware("http")
    async def attach_identity_context(request: Request, call_next):
        request.state.authenticated_session = None
        request.state.authentication_error = None

        if service.has_identity_material(request):
            try:
                request.state.authenticated_session = service.authenticate_request(request)
            except AuthenticationError as exc:
                request.state.authentication_error = exc

        return await call_next(request)

    @app.get("/health")
    def health() -> dict[str, str]:
        return {"status": "ok"}

    @app.get("/auth/me")
    def read_me(
        authenticated_session: AuthenticatedSession = Depends(require_authenticated_session),
    ) -> dict[str, object]:
        return _session_payload(authenticated_session)

    @app.get("/auth/protected/upload")
    def protected_upload(
        authenticated_session: AuthenticatedSession = Depends(require_permission("upload")),
    ) -> dict[str, object]:
        return {"ok": True, "permission": "upload", "subject": authenticated_session.identity.subject}

    @app.get("/auth/protected/validate")
    def protected_validate(
        authenticated_session: AuthenticatedSession = Depends(require_permission("validate")),
    ) -> dict[str, object]:
        return {
            "ok": True,
            "permission": "validate",
            "subject": authenticated_session.identity.subject,
        }

    return app


def _build_repository_from_env() -> SQLAlchemyUserIdentityRepository:
    database_url = os.getenv("DATABASE_URL")
    if database_url is None or database_url.strip() == "":
        raise RuntimeError(
            "DATABASE_URL is required when no repository is injected into create_app()."
        )

    engine = create_engine(_normalize_sqlalchemy_url(database_url), future=True)
    return SQLAlchemyUserIdentityRepository(session_factory=build_session_factory(engine))


def _normalize_sqlalchemy_url(url: str) -> str:
    if url.startswith("postgresql://"):
        return url.replace("postgresql://", "postgresql+psycopg://", 1)
    return url


def _session_payload(authenticated_session: AuthenticatedSession) -> dict[str, object]:
    return {
        "user_id": authenticated_session.user.id,
        "external_subject": authenticated_session.user.external_subject,
        "email": authenticated_session.identity.email,
        "display_name": authenticated_session.identity.display_name,
        "groups": list(authenticated_session.identity.groups),
        "roles": list(authenticated_session.identity.roles),
        "primary_role": authenticated_session.identity.primary_role,
        "permissions": list(authenticated_session.identity.permissions),
        "provider": authenticated_session.identity.provider,
        "last_login_at": (
            authenticated_session.user.last_login_at.isoformat()
            if authenticated_session.user.last_login_at is not None
            else None
        ),
    }
